def lis_strict_len(xs: list[int]) -> int:
    """
    Return the length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search for O(n log n) time.
    """
    import bisect

    if not xs:
        return 0

    # tails[i] = smallest possible tail value of an increasing subsequence of length i+1
    tails = []
    for x in xs:
        # Find position to replace: first element >= x (since we need strictly increasing)
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)
