def lru_trace_sim(cap: int, ops: list[tuple[str, int, int]]) -> list[int]:
    from collections import OrderedDict

    cache = OrderedDict()
    results = []

    for op, k, v in ops:
        if op == 'PUT':
            if k in cache:
                # Update value and move to end (most recent)
                cache.move_to_end(k)
                cache[k] = v
            else:
                # Insert new entry
                if len(cache) >= cap:
                    # Evict least recently used (first item)
                    cache.popitem(last=False)
                cache[k] = v
        elif op == 'GET':
            if k in cache:
                # Access updates recency
                cache.move_to_end(k)
                results.append(cache[k])
            else:
                results.append(-1)
        else:
            raise ValueError(f"Unsupported operation: {op}")

    return results
