def max_bounded_submatrix(grid: list[list[int]], max_h: int, max_w: int) -> int:
    if not grid or not grid[0]:
        raise ValueError("grid must be non-empty")
    n, m = len(grid), len(grid[0])
    # Prefix sums for rows to allow O(1) column sum between rows r1..r2
    row_pref = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n):
        for j in range(m):
            row_pref[i + 1][j + 1] = row_pref[i + 1][j] + grid[i][j]
    for i in range(n):
        for j in range(m + 1):
            row_pref[i + 1][j] += row_pref[i][j]

    best = None

    # Iterate over top row
    for top in range(n):
        # accumulate column sums for varying bottom within height limit
        col_sum = [0] * m
        for bottom in range(top, min(n, top + max_h)):
            # update col_sum to include row 'bottom'
            for c in range(m):
                col_sum[c] += grid[bottom][c]

            # Now we need max subarray sum with width <= max_w on col_sum
            # Use prefix sums over columns
            pref = [0]
            for val in col_sum:
                pref.append(pref[-1] + val)

            # deque stores indices of pref in increasing order of pref value
            from collections import deque
            dq = deque()
            # initialize with index 0
            dq.append(0)
            for j in range(1, m + 1):
                # remove indices that are out of window (j - idx > max_w)
                while dq and j - dq[0] > max_w:
                    dq.popleft()
                # candidate sum = pref[j] - min pref in window
                cur = pref[j] - pref[dq[0]]
                if best is None or cur > best:
                    best = cur
                # maintain monotonic increasing pref values in deque
                while dq and pref[dq[-1]] >= pref[j]:
                    dq.pop()
                dq.append(j)

    return best
