def next_greater_circular(xs: list[int]) -> list[int]:
    n = len(xs)
    if n == 0:
        return []
    res = [-1] * n
    stack = []  # indices of decreasing sequence
    # Loop twice to simulate circularity
    for i in range(2 * n):
        idx = i % n
        while stack and xs[idx] > xs[stack[-1]]:
            res[stack.pop()] = xs[idx]
        if i < n:
            stack.append(idx)
    return res
