def strict_third_majority(xs: list[int]) -> list[int]:
    """
    Return a sorted list of distinct elements that appear strictly more than len(xs)//3 times.
    Uses the linear-time O(1)-space Boyer-Moore majority vote algorithm extended for the 1/3 threshold.
    """
    n = len(xs)
    if n == 0:
        return []

    # First pass: find up to two candidates
    cand1 = cand2 = None
    cnt1 = cnt2 = 0
    for x in xs:
        if cand1 == x:
            cnt1 += 1
        elif cand2 == x:
            cnt2 += 1
        elif cnt1 == 0:
            cand1, cnt1 = x, 1
        elif cnt2 == 0:
            cand2, cnt2 = x, 1
        else:
            cnt1 -= 1
            cnt2 -= 1

    # Second pass: verify the counts
    cnt1 = cnt2 = 0
    for x in xs:
        if x == cand1:
            cnt1 += 1
        elif x == cand2:
            cnt2 += 1

    threshold = n // 3
    result = []
    if cnt1 > threshold:
        result.append(cand1)
    if cnt2 > threshold:
        result.append(cand2)

    return sorted(set(result))
