        c_mod = c % MOD
        # evaluate term
        val = (val + c_mod * power) % MOD
        # derivative term (skip i=0)
        if i:
            deriv = (deriv + i * c_mod % MOD * (power * pow(x_mod, MOD-2, MOD) % MOD)) % MOD
        # update power for next i
        power = (power * x_mod) % MOD
    return (val, deriv)
