def valid_brackets_escaped(s: str) -> bool:
    """
    Returns True iff all parentheses, square brackets and curly braces that appear
    outside of double‑quoted string literals are balanced, and all double‑quoted
    strings are properly closed. Inside a string a backslash escapes the next
    character (including another backslash or a quote). An isolated backslash at
    the end of a string literal makes the input invalid.
    """
    stack = []
    opening = {'(': ')', '[': ']', '{': '}'}
    closing = {')': '(', ']': '[', '}': '{'}

    in_string = False
    i = 0
    n = len(s)

    while i < n:
        ch = s[i]

        if in_string:
            if ch == '\\':
                # Escape must have a following character
                if i + 1 >= n:
                    return False
                i += 1  # skip the escaped character
            elif ch == '"':
                in_string = False
        else:
            if ch == '"':
                in_string = True
            elif ch in opening:
                stack.append(ch)
            elif ch in closing:
                if not stack or stack[-1] != closing[ch]:
                    return False
                stack.pop()
        i += 1

    # Must not be inside an unclosed string and stack must be empty
    return not in_string and not stack
```

