from math import gcd

def exact_fraction_sum(fracs: list[tuple[int, int]]) -> tuple[int, int]:
    """
    Sum a list of rational numbers given as (numerator, denominator) pairs.
    Returns the result as a reduced fraction (p, q) with q > 0 and gcd(|p|, q) == 1.
    An empty list yields (0, 1).
    """
    if not fracs:
        return (0, 1)

    num, den = 0, 1  # start with 0/1

    for n, d in fracs:
        if d == 0:
            raise ZeroDivisionError("Denominator cannot be zero")
        # Normalize sign: denominator positive
        if d < 0:
            n, d = -n, -d

        # Compute least common multiple of denominators to keep size small
        g = gcd(den, d)
        lcm = den // g * d

        # Scale numerators to the common denominator and add
        new_num = num * (lcm // den) + n * (lcm // d)

        if new_num == 0:
            num, den = 0, 1
        else:
            g2 = gcd(abs(new_num), lcm)
            num, den = new_num // g2, lcm // g2

    # Ensure denominator positive (should already be)
    if den < 0:
        num, den = -num, -den

    return (num, den)
